DROP TABLE IF EXISTS `audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `audit_log` (
  `audit_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'Primary key (auto-generated when left empty). Format AUD-00001',
  `table_name` varchar(64) NOT NULL,
  `record_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Primary key value of the changed row in table_name, e.g. AST-0007',
  `action` enum('INSERT','UPDATE','DELETE') NOT NULL,
  `changed_by` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to users.user_id',
  `changed_at` datetime NOT NULL DEFAULT current_timestamp(),
  `old_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`old_values`)),
  `new_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`new_values`)),
  `ip_address` varchar(45) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`audit_id`),
  KEY `ix_audit_record` (`table_name`,`record_id`),
  KEY `ix_audit_when` (`changed_at`),
  KEY `ix_audit_user` (`changed_by`),
  CONSTRAINT `fk_audit_user` FOREIGN KEY (`changed_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_audit_log_id_format` CHECK (`audit_id` regexp '^AUD-[0-9]{5,}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

