  `segment_register_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'FK to segment_register.segment_register_id',
  `switchgear_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to switchgear.switchgear_id',
  `switch_ref` varchar(30) NOT NULL,
  PRIMARY KEY (`segment_switchgear_id`),
