  CONSTRAINT `chk_segment_switchgear_id_format` CHECK (`segment_switchgear_id` regexp '^SSW-[0-9]{5,}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
