  `segment_transformer_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'Primary key (auto-generated when left empty). Format STF-00001',
  `segment_register_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'FK to segment_register.segment_register_id',
  `transformer_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to transformers.transformer_id',
  `transformer_ref` varchar(60) NOT NULL,
  PRIMARY KEY (`segment_transformer_id`),
