  CONSTRAINT `fk_st_tx` FOREIGN KEY (`transformer_id`) REFERENCES `transformers` (`transformer_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_segment_transformer_id_format` CHECK (`segment_transformer_id` regexp '^STF-[0-9]{5,}$')
