--
-- Table structure for table `switchgear`
--

DROP TABLE IF EXISTS `switchgear`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `switchgear` (
  `switchgear_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'Primary key (auto-generated when left empty). Format SWG-00001',
  `csc_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'FK to csc_depots.csc_id',
  `asset_type_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to asset_types.asset_type_id',
  `node_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to network_nodes.node_id',
  `asset_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to assets.asset_id',
  `switch_code` varchar(30) NOT NULL,
  `switch_name` varchar(200) DEFAULT NULL,
  `nearest_substation` varchar(120) DEFAULT NULL,
  `status` enum('ACTIVE','PLANNED','RETIRED') NOT NULL DEFAULT 'ACTIVE',
  `remarks` text DEFAULT NULL,
  `source_file` varchar(80) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`switchgear_id`),
  UNIQUE KEY `uq_switch_code` (`switch_code`),
  KEY `ix_sw_csc` (`csc_id`),
  KEY `ix_sw_type` (`asset_type_id`),
  KEY `ix_sw_node` (`node_id`),
  KEY `ix_sw_substation` (`nearest_substation`),
  KEY `fk_sw_asset` (`asset_id`),
  CONSTRAINT `fk_sw_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sw_csc` FOREIGN KEY (`csc_id`) REFERENCES `csc_depots` (`csc_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_sw_node` FOREIGN KEY (`node_id`) REFERENCES `network_nodes` (`node_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sw_type` FOREIGN KEY (`asset_type_id`) REFERENCES `asset_types` (`asset_type_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_switchgear_id_format` CHECK (`switchgear_id` regexp '^SWG-[0-9]{5,}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

