--
-- Table structure for table `transformers`
--

DROP TABLE IF EXISTS `transformers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `transformers` (
  `transformer_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'Primary key (auto-generated when left empty). Format TRF-00001',
  `csc_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'FK to csc_depots.csc_id',
  `node_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to network_nodes.node_id',
  `asset_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to assets.asset_id',
  `asset_type_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to asset_types.asset_type_id',
  `old_sin_no` varchar(40) DEFAULT NULL,
  `new_sin_no` varchar(40) DEFAULT NULL,
  `substation_name` varchar(255) NOT NULL,
  `transformer_type` varchar(60) DEFAULT NULL,
  `capacity_kva` decimal(10,2) DEFAULT NULL,
  `transformer_no` varchar(60) DEFAULT NULL,
  `manufacturer` varchar(80) DEFAULT NULL,
  `fly_length_km` decimal(9,3) DEFAULT NULL,
  `combined_fly_length_km` decimal(9,3) DEFAULT NULL,
  `free_wayleave_km` decimal(9,3) DEFAULT NULL,
  `wayleave_distance_km` decimal(9,3) DEFAULT NULL,
  `total_distance_km` decimal(9,3) DEFAULT NULL,
  `quantity` int(10) unsigned NOT NULL DEFAULT 1,
  `condition_status` enum('NEW','GOOD','FAIR','POOR','FAULTY','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  `status` enum('ACTIVE','PLANNED','RETIRED') NOT NULL DEFAULT 'ACTIVE',
  `install_date` date DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `source_file` varchar(80) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`transformer_id`),
  KEY `ix_tx_csc` (`csc_id`),
  KEY `ix_tx_node` (`node_id`),
  KEY `ix_tx_asset` (`asset_id`),
  KEY `ix_tx_type` (`asset_type_id`),
  KEY `ix_tx_new_sin` (`new_sin_no`),
  KEY `ix_tx_old_sin` (`old_sin_no`),
  KEY `ix_tx_serial` (`transformer_no`),
  KEY `ix_tx_capacity` (`capacity_kva`),
  KEY `ix_tx_raw_type` (`transformer_type`),
  KEY `ix_tx_geo` (`latitude`,`longitude`),
  CONSTRAINT `fk_tx_asset` FOREIGN KEY (`asset_id`) REFERENCES `assets` (`asset_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_tx_csc` FOREIGN KEY (`csc_id`) REFERENCES `csc_depots` (`csc_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_tx_node` FOREIGN KEY (`node_id`) REFERENCES `network_nodes` (`node_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_tx_type` FOREIGN KEY (`asset_type_id`) REFERENCES `asset_types` (`asset_type_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `chk_transformers_id_format` CHECK (`transformer_id` regexp '^TRF-[0-9]{5,}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

