/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tx_bi` BEFORE INSERT ON `transformers`
 FOR EACH ROW BEGIN
    DECLARE v_is_line TINYINT(1);
    IF NEW.`transformer_id` IS NULL OR NEW.`transformer_id` = '' THEN
        SET NEW.`transformer_id` = fn_next_id('transformers');
    END IF;
    IF NEW.asset_type_id IS NOT NULL THEN
        SELECT is_line_asset INTO v_is_line
          FROM asset_types WHERE asset_type_id = NEW.asset_type_id;
        IF v_is_line = 1 THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'A transformer cannot be classified as a line (span) asset type.';
        END IF;
    END IF;
END */;;
DELIMITER ;
