--
-- Table structure for table `users`
--

DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `user_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '' COMMENT 'Primary key (auto-generated when left empty). Format USR-001',
  `role_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'FK to roles.role_id',
  `requested_role_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to roles.role_id',
  `area_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to areas.area_id',
  `csc_id` varchar(12) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT 'FK to csc_depots.csc_id',
  `username` varchar(50) NOT NULL,
  `employee_no` varchar(30) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `designation` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `phone` varchar(25) DEFAULT NULL,
  `registration_source` enum('ADMIN_CREATED','SELF_REGISTERED') NOT NULL DEFAULT 'ADMIN_CREATED',
  `scope_assigned` tinyint(1) NOT NULL DEFAULT 1,
  `email_verified_at` datetime DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `last_login_at` datetime DEFAULT NULL,
  `failed_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_username` (`username`),
  UNIQUE KEY `uq_user_email` (`email`),
  UNIQUE KEY `uq_users_employee_no` (`employee_no`),
  KEY `ix_users_role` (`role_id`),
  KEY `ix_users_csc` (`csc_id`),
  KEY `ix_users_area` (`area_id`),
  KEY `ix_users_phone` (`phone`),
  KEY `ix_users_source` (`registration_source`),
  KEY `fk_users_requested_role` (`requested_role_id`),
  CONSTRAINT `fk_users_area` FOREIGN KEY (`area_id`) REFERENCES `areas` (`area_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_users_csc` FOREIGN KEY (`csc_id`) REFERENCES `csc_depots` (`csc_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_users_requested_role` FOREIGN KEY (`requested_role_id`) REFERENCES `roles` (`role_id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles` (`role_id`) ON UPDATE CASCADE,
  CONSTRAINT `chk_users_id_format` CHECK (`user_id` regexp '^USR-[0-9]{3,}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

